def shortest_path(graph, source, target):
    from collections import deque
    import heapq

    def bfs(graph, source, target):
        queue = deque([(source, [source])])
        visited = set()

        while queue:
            node, path = queue.popleft()
            if node == target:
                return path
            if node not in visited:
                visited.add(node)
                for neighbor, _ in graph.get(node, []):
                    if neighbor not in visited:
                        queue.append((neighbor, path + [neighbor]))
        return None

    def dijkstra(graph, source):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        pq = [(0, source)]
        path = {source: []}

        while pq:
            current_distance, current_node = heapq.heappop(pq)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph.get(current_node, []):
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(pq, (distance, neighbor))
                    path[neighbor] = path[current_node] + [neighbor]

        return distances, path

    # Step 1: Find a path in the unweighted graph
    bfs_result = bfs(graph, source, target)
    if bfs_result is None:
        return float('inf'), None

    # Step 2: Convert the unweighted path to a weighted path
    distances, path = dijkstra(graph, source)
    if target not in path:
        return float('inf'), None

    return distances[target], path[target]

